using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class RemainingPostPlay {public static object Run(){if(Application.isPlaying)throw new Exception("Stop Play first");var s=SceneManager.GetActiveScene();string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_Remaining_PostPlay_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(backup);bool dirty=s.isDirty;if(!EditorSceneManager.SaveScene(s,backup+"/editing_before_save.unity",true))throw new Exception("Backup failed");if(dirty&&!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");foreach(string label in new[]{"living_unculled","living","control","meal","cooling","lift","stairs","corridor"}){string path="Assets/Temp/Remaining_Play_"+label+".png";if(AssetDatabase.LoadAssetAtPath<Texture2D>(path))AssetDatabase.DeleteAsset(path);}var p=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var result=new{backup,preservedDirty=dirty,scene=s.path,dirty=s.isDirty,player=new[]{p.transform.position.x,p.transform.position.y,p.transform.position.z},runInBackground=PlayerSettings.runInBackground};File.WriteAllText(repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/post_play.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
